/// <summary>
/// One return reason code (ReturnReasonCode) for purchase returns on the handheld.
/// </summary>
[DataContractAttribute]
class HSMobileOpsReturnReason
{
    str code;
    str description;
}

Method.Source:
[DataMemberAttribute('Code')]
public str parmCode(str _value = code)
{
    code = _value;
    return code;
}

[DataMemberAttribute('Description')]
public str parmDescription(str _value = description)
{
    description = _value;
    return description;
}
